import os, subprocess, sys
sys.path.insert(0, '_tools')
import kbcommon
def pack(roots, root, q):
    env = dict(os.environ, KB_ROOTS=os.pathsep.join(roots))
    return subprocess.run([sys.executable, '_tools/rag.py', 'pack', '--root', root, '--format', 'concise', q], env=env, capture_output=True, text=True).stdout
def load(name):
    try:
        return kbcommon.load_root('_tools/fixtures/evidence/' + name)
    except kbcommon.RootError as e:
        sys.exit('fixture root %s: %s' % (name, str(e)[:200]))

bad = []
for name, kind in (('both', 'COMMUNITY'), ('missing', 'UNK'), ('unknown', 'BOGUS')):
    try:
        kbcommon.load_root('_tools/fixtures/evidence/' + name)
    except kbcommon.RootError as e:
        kind in str(e) or bad.append('%s: message does not name %s: %s' % (name, kind, str(e)[:120]))
    else:
        bad.append('%s: accepted' % name)
bad and sys.exit('; '.join(bad))
